import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { subscribe } from "@/lib/event-bus";
import { newId } from "@/lib/id";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { bulkArchiveIssuesSchema } from "@/schemas/issue";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as issueService from "@/server/services/issue-service";
import type { IssueId, UserId } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let a: Tenant;
let b: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  a = await createTenant("bulka");
  b = await createTenant("bulkb");
});

afterAll(() => {
  cleanup();
});

async function insertAs(
  t: Tenant,
  title: string,
  authorId: UserId,
  assigneeId: UserId | null = null,
) {
  const number = await issueRepo.nextIssueNumber(t.org.id, t.project.id);
  return issueRepo.insertIssue(
    issueInput(t.org.id, t.project.id, { title, assigneeId }),
    authorId,
    number,
  );
}

function collectArchived() {
  const received: { issueId: IssueId; projectId: string; actorId: string | null; orgId: string }[] = [];
  const off = subscribe("issue.archived", (payload) => {
    received.push({
      issueId: payload.issueId,
      projectId: payload.projectId,
      actorId: payload.actorId,
      orgId: payload.orgId,
    });
  });
  return { received, off };
}

async function archivedAtOf(t: Tenant, id: IssueId) {
  return (await issueRepo.findIssueById(t.org.id, id))?.archivedAt ?? "missing";
}

describe("bulkArchiveIssues (scratch)", () => {
  it("rejects an orgId that is not the actor's organization", async () => {
    const issue = await insertAs(a, "foreign org", a.userIds.member);
    await expect(
      issueService.bulkArchiveIssues(a.actors.owner, {
        orgId: b.org.id,
        issueIds: [issue.id],
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);
    expect(await archivedAtOf(a, issue.id)).toBeNull();
  });

  it("de-duplicates, keeps request order, skips unknown/foreign/archived, leaves skipped rows alone", async () => {
    const x1 = await insertAs(a, "x1", a.userIds.member);
    const x2 = await insertAs(a, "x2", a.userIds.member);
    const x3 = await insertAs(a, "x3", a.userIds.member);
    const foreign = await insertAs(b, "foreign", b.userIds.member);
    const pre = await insertAs(a, "pre-archived", a.userIds.member);
    await issueService.archiveIssue(a.actors.member, a.org.id, pre.id);
    const preStamp = await archivedAtOf(a, pre.id);
    const unknown = newId() as IssueId;

    const { received, off } = collectArchived();
    try {
      const result = await issueService.bulkArchiveIssues(a.actors.member, {
        orgId: a.org.id,
        issueIds: [x3.id, unknown, x1.id, x3.id, foreign.id, pre.id, x2.id, x1.id],
      });

      expect(result.archived).toEqual([x3.id, x1.id, x2.id]);
      expect(result.skipped).toEqual([unknown, foreign.id, pre.id]);
      expect(received.map((r) => r.issueId)).toEqual([x3.id, x1.id, x2.id]);
      expect(received.every((r) => r.orgId === a.org.id)).toBe(true);
      expect(received.every((r) => r.actorId === a.userIds.member)).toBe(true);

      for (const issue of [x1, x2, x3]) {
        expect(await archivedAtOf(a, issue.id)).not.toBeNull();
      }
      expect(await archivedAtOf(a, pre.id)).toBe(preStamp);
      expect(await archivedAtOf(b, foreign.id)).toBeNull();
    } finally {
      off();
    }
  });

  it("denies the whole call, archiving nothing and publishing nothing, when one issue fails the check", async () => {
    const viewerOwn = await insertAs(a, "viewer authored", a.userIds.viewer);
    const adminOwn = await insertAs(a, "admin authored", a.userIds.admin);

    const { received, off } = collectArchived();
    try {
      await expect(
        issueService.bulkArchiveIssues(a.actors.viewer, {
          orgId: a.org.id,
          issueIds: [viewerOwn.id, adminOwn.id],
        }),
      ).rejects.toBeInstanceOf(PermissionDeniedError);

      expect(await archivedAtOf(a, viewerOwn.id)).toBeNull();
      expect(await archivedAtOf(a, adminOwn.id)).toBeNull();
      expect(received).toHaveLength(0);
    } finally {
      off();
    }
  });

  it("lets a viewer archive issues they authored or are assigned to, one event each", async () => {
    const authored = await insertAs(a, "viewer authored ok", a.userIds.viewer);
    const assigned = await insertAs(a, "viewer assigned", a.userIds.admin, a.userIds.viewer);

    const { received, off } = collectArchived();
    try {
      const result = await issueService.bulkArchiveIssues(a.actors.viewer, {
        orgId: a.org.id,
        issueIds: [authored.id, assigned.id],
      });
      expect(result).toEqual({ archived: [authored.id, assigned.id], skipped: [] });
      expect(received.map((r) => r.issueId)).toEqual([authored.id, assigned.id]);
    } finally {
      off();
    }
  });

  it("does not permission-check skipped ids", async () => {
    const adminOwned = await insertAs(a, "admin owned, pre-archived", a.userIds.admin);
    await issueService.archiveIssue(a.actors.admin, a.org.id, adminOwned.id);
    const foreign = await insertAs(b, "foreign for viewer", b.userIds.admin);

    const result = await issueService.bulkArchiveIssues(a.actors.viewer, {
      orgId: a.org.id,
      issueIds: [adminOwned.id, foreign.id, newId() as IssueId],
    });
    expect(result.archived).toEqual([]);
    expect(result.skipped).toEqual([adminOwned.id, foreign.id, expect.any(String)]);
  });

  it("findIssuesByIds: org-scoped, archived included, empty input short-circuits", async () => {
    const live = await insertAs(a, "find live", a.userIds.member);
    const dead = await insertAs(a, "find dead", a.userIds.member);
    await issueService.archiveIssue(a.actors.member, a.org.id, dead.id);
    const foreign = await insertAs(b, "find foreign", b.userIds.member);

    const found = await issueRepo.findIssuesByIds(a.org.id, [live.id, dead.id, foreign.id]);
    expect(found.map((i) => i.id).sort()).toEqual([live.id, dead.id].sort());
    expect(found.find((i) => i.id === dead.id)?.archivedAt).not.toBeNull();
    expect(await issueRepo.findIssuesByIds(a.org.id, [])).toEqual([]);
  });

  it("schema bounds: 1..50 ids, ULID-validated", () => {
    const ok = newId();
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: a.org.id, issueIds: [] }).success).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({
        orgId: a.org.id,
        issueIds: Array.from({ length: 51 }, () => newId()),
      }).success,
    ).toBe(false);
    expect(
      bulkArchiveIssuesSchema.safeParse({
        orgId: a.org.id,
        issueIds: Array.from({ length: 50 }, () => newId()),
      }).success,
    ).toBe(true);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: a.org.id, issueIds: [ok, "nope"] }).success).toBe(false);
    expect(bulkArchiveIssuesSchema.safeParse({ orgId: "nope", issueIds: [ok] }).success).toBe(false);
  });
});

